import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
// Font Loading - Module level calls to block frame 0 until ready
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: robotoMono } = loadRobotoMono();

// Single, inline Zod schema export


export type MissileCostProps = Record<string, any>;

// --- Sub-components for visual elements ---

const BackgroundGrid: React.FC<{ color: string }> = ({ color }) => (
  <AbsoluteFill style={{ overflow: "hidden", opacity: 0.04, pointerEvents: "none" }}>
    {Array.from({ length: 20 }).map((_, i) => (
      <div
        key={`h-${i}`}
        style={{
          position: "absolute",
          top: `${(i + 1) * 5.2}%`,
          left: 0,
          width: "100%",
          height: "1px",
          backgroundColor: color,
        }}
      />
    ))}
    {Array.from({ length: 40 }).map((_, i) => (
      <div
        key={`v-${i}`}
        style={{
          position: "absolute",
          left: `${(i + 1) * 2.5}%`,
          top: 0,
          height: "100%",
          width: "1px",
          backgroundColor: color,
        }}
      />
    ))}
  </AbsoluteFill>
);

const HudCorners: React.FC<{ color: string }> = ({ color }) => {
  const size = 60;
  const stroke = 3;
  return (
    <AbsoluteFill style={{ pointerEvents: "none", padding: "60px" }}>
      <div style={{ position: "absolute", top: "60px", left: "60px", width: size, height: size, borderTop: `${stroke}px solid ${color}`, borderLeft: `${stroke}px solid ${color}`, opacity: 0.5 }} />
      <div style={{ position: "absolute", top: "60px", right: "60px", width: size, height: size, borderTop: `${stroke}px solid ${color}`, borderRight: `${stroke}px solid ${color}`, opacity: 0.5 }} />
      <div style={{ position: "absolute", bottom: "60px", left: "60px", width: size, height: size, borderBottom: `${stroke}px solid ${color}`, borderLeft: `${stroke}px solid ${color}`, opacity: 0.5 }} />
      <div style={{ position: "absolute", bottom: "60px", right: "60px", width: size, height: size, borderBottom: `${stroke}px solid ${color}`, borderRight: `${stroke}px solid ${color}`, opacity: 0.5 }} />
    </AbsoluteFill>
  );
};

const MissileSVG: React.FC<{ color: string; flameScale: number }> = ({ color, flameScale }) => {
  // Calculate flame extension deterministically to avoid SVG scale transforms which can be buggy
  const flameTipXStr = (80 - 120 * flameScale).toFixed(1);
  const innerFlameTipXStr = (80 - 80 * flameScale).toFixed(1);

  return (
    <svg
      viewBox="0 0 600 160"
      style={{
        width: "100%",
        overflow: "visible",
        filter: "drop-shadow(0 20px 25px rgba(0,0,0,0.5))",
      }}
    >
      <defs>
        <filter id="blurBase" x="-100%" y="-100%" width="300%" height="300%">
          <feGaussianBlur stdDeviation="4" />
        </filter>
        <filter id="blurInner" x="-100%" y="-100%" width="300%" height="300%">
          <feGaussianBlur stdDeviation="2" />
        </filter>
      </defs>

      {/* Flame Base */}
      <path
        d={`M 80 70 L ${flameTipXStr} 80 L 80 90 Z`}
        fill="#f59e0b"
        filter="url(#blurBase)"
      />
      <path
        d={`M 80 75 L ${innerFlameTipXStr} 80 L 80 85 Z`}
        fill="#fef08a"
        filter="url(#blurInner)"
      />

      {/* Exhaust / Engine section */}
      <rect x="80" y="65" width="40" height="30" fill="#334155" rx="4" />

      {/* Main Body */}
      <path
        d="M 120 60 L 500 60 C 560 60, 590 70, 600 80 C 590 90, 560 100, 500 100 L 120 100 Z"
        fill={color}
      />

      {/* Subtle Highlight Reflection */}
      <path
        d="M 140 60 L 480 60 C 530 60, 560 65, 570 70 C 560 75, 530 80, 480 80 L 140 80 Z"
        fill="#ffffff"
        opacity="0.1"
      />

      {/* Tail Fins */}
      <path d="M 120 60 L 90 10 L 160 60 Z" fill={color} />
      <path d="M 120 100 L 90 150 L 160 100 Z" fill={color} />

      {/* Window / Sensor */}
      <ellipse cx="560" cy="80" rx="15" ry="6" fill="#1e293b" />
    </svg>
  );
};

// --- Main Component ---

const MissileCost: React.FC<MissileCostProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#ef4444",
  textColor = "#f8fafc",
  maxCost = 1000000,
  titleText = "STRIKE ASSET",
  subtitleText = "The estimated operational cost of a single modern missile deployment.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parse background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings & Durations
  const counterDuration = Math.max(30, Math.min(120, fps * durationInSeconds * 0.4));
  const countStartFrame = 30;
  const countEndFrame = countStartFrame + counterDuration;

  // --- Logic: Counter ---
  const countProgress = interpolate(
    frame,
    [countStartFrame, countEndFrame],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.poly(3)),
    }
  );

  const currentCost = Math.floor(countProgress * maxCost);
  const formattedCost = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(currentCost);

  // --- Logic: Animations ---
  const isCountFinished = frame >= countEndFrame;
  const popSpring = spring({
    frame: frame - countEndFrame,
    fps,
    config: { damping: 12, stiffness: 200 },
  });
  
  // Text element reveals
  const titleOpacity = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(
    spring({ frame: frame - 10, fps, config: { damping: 14 } }),
    [0, 1],
    [30, 0]
  );

  const counterOpacity = interpolate(frame, [20, 40], [0, 1], { extrapolateRight: "clamp" });
  const counterY = interpolate(
    spring({ frame: frame - 20, fps, config: { damping: 14 } }),
    [0, 1],
    [30, 0]
  );
  // Add slight pop when it hits the max value
  const counterScale = 1 + interpolate(popSpring, [0, 1], [0, 0.05]);

  const subOpacity = interpolate(frame, [40, 60], [0, 1], { extrapolateRight: "clamp" });
  const subY = interpolate(
    spring({ frame: frame - 40, fps, config: { damping: 14 } }),
    [0, 1],
    [30, 0]
  );

  // --- Logic: Missile Motion ---
  // Flies in from the left side
  const missileEnter = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, stiffness: 60 },
  });
  
  const missileX = interpolate(missileEnter, [0, 1], [-width, 0]);
  const hoverY = Math.sin(frame / 15) * 15;
  const hoverRot = Math.cos(frame / 20) * 1.5;
  const flameScale = 0.8 + Math.abs(Math.sin(frame * 0.5)) * 0.4;

  // HUD Dynamic Values
  const lat = interpolate(frame, [0, 300], [34.0522, 34.058]).toFixed(4);
  const lng = interpolate(frame, [0, 300], [-118.2437, -118.25]).toFixed(4);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <BackgroundGrid color={textColor} />
      <HudCorners color={primaryColor} />

      {/* Top Left HUD Coordinates */}
      <div
        style={{
          position: "absolute",
          top: "80px",
          left: "80px",
          fontFamily: robotoMono,
          fontSize: "18px",
          color: textColor,
          opacity: 0.4,
          display: "flex",
          flexDirection: "column",
          gap: "4px",
          transition: "none",
        }}
      >
        <span>SYS.TRK.ACTV</span>
        <span>LAT: {lat} N</span>
        <span>LNG: {lng} W</span>
      </div>

      <div
        style={{
          display: "flex",
          flexDirection: "row",
          width: "100%",
          height: "100%",
          padding: "0 140px",
        }}
      >
        {/* Left Column - Text Content */}
        <div
          style={{
            width: "55%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            zIndex: 10,
          }}
        >
          <div
            style={{
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
              marginBottom: "24px",
            }}
          >
            <h2
              style={{
                fontFamily: spaceGrotesk,
                fontSize: "32px",
                letterSpacing: "0.2em",
                color: primaryColor,
                margin: 0,
                fontWeight: 600,
              }}
            >
              {titleText.toUpperCase()}
            </h2>
          </div>

          <div
            style={{
              opacity: counterOpacity,
              transform: `translateY(${counterY}px) scale(${isCountFinished ? counterScale : 1})`,
              transformOrigin: "left center",
              transition: "none",
              marginBottom: "32px",
            }}
          >
            <h1
              style={{
                fontFamily: robotoMono,
                fontSize: "130px",
                color: textColor,
                margin: 0,
                fontWeight: 700,
                lineHeight: 1,
                textShadow: isCountFinished ? `0 0 40px rgba(255,255,255,0.15)` : "none",
              }}
            >
              {formattedCost}
            </h1>
          </div>

          <div
            style={{
              opacity: subOpacity,
              transform: `translateY(${subY}px)`,
              transition: "none",
              maxWidth: "85%",
            }}
          >
            <p
              style={{
                fontFamily: spaceGrotesk,
                fontSize: "36px",
                color: textColor,
                margin: 0,
                opacity: 0.8,
                lineHeight: 1.4,
              }}
            >
              {subtitleText}
            </p>
          </div>
        </div>

        {/* Right Column - Missile Graphic */}
        <div
          style={{
            width: "45%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            position: "relative",
          }}
        >
          <div
            style={{
              width: "120%", // Allow graphic to bleed slightly for scale
              transform: `translate(${missileX}px, ${hoverY}px) rotate(${hoverRot}deg)`,
              transition: "none",
              willChange: "transform",
            }}
          >
            <MissileSVG color={primaryColor} flameScale={flameScale} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MissileCost;